const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Records remain local fictional state; viewing a chart never transfers a paper object.
export function onlineRecords(s,events={}){
  const records=[],add=r=>{if(!records.some(x=>x.id===r.id))records.push(r);};
  if(s.fish){const t=s.fish;add({id:'fish',name:t.patient.name,title:'魚刺會診',rows:[['主訴','吃魚後喉嚨異物感，急診初評呼吸平順。'],['檢查','Lateral view 已完成，可直接在線上影像系統查看。']],reportTitle:'Lateral view',reportText:t.xray.replace(/^NP：「|」$/g,''),type:'xray',suspected:t.xraySuspicious});}
  if(s.wardNG){const p=s.wardNG.patient;add({id:'ng',name:p.name,title:'NG 放置困難',rows:[['原病房',p.ward],['先前處理',p.attempt],['相關病史',p.history],['紀錄','電子會診與放置紀錄，可在電腦查閱。']]});}
  if(s.hearingConsult){const t=s.hearingConsult,p=t.patient,ready=['call-patient','review','history','plan','steroid-review','clean','recheck','report','done'].includes(t.stage);add({id:'sudden',name:p.name,title:'聽力會診',rows:[['原病房',p.ward],['主訴',p.sideText+'聽不清楚'],['病史／用藥',p.chronic],['檢查狀態',ready?'聽力圖已上傳，可在線上報告查看。':'聽力檢查尚未完成。']],reportTitle:ready?'聽力圖':null,type:'consult'});}
  if(s.hearing){add({id:'hearing-paperwork',name:s.hearing.patient.name,title:'聽障鑑定',rows:[['檢查','聽力圖由電腦查看，依線上報告讀取左右耳四頻資料。'],['文件','鑑定文件仍依本次門診流程交給診間護理師。']],reportTitle:'聽力圖',type:'hearing'});}
  for(const t of [...Object.values(s.tubes||{}),s.practiceTube].filter(Boolean))add({id:t.caseId,name:t.patient.name,title:t.caseId==='outpatientNG'?'門診換 NG':'門診換氣切管',rows:[['本次管型',t.code],['換管紀錄',t.recorded?'已寫入電子病歷。':'尚未完成電子病歷紀錄。'],['掛號單','護理師留在工作桌上的掛號單，完成後放回桌上。']]});
  const p=s.run?.phases?.[s.phase],c=events[p?.case];if(c&&c.category!=='daily'&&!records.some(r=>r.id===p.case))add({id:p.case,name:c.patient||'本次病人',title:c.title,rows:[['電子會診',c.call],['來源',c.source]]});
  return records;
}
export function lateralViewSVG(suspected=false){return`<svg class="ehr-xray" viewBox="0 0 460 310" role="img" aria-label="側頸影像的遊戲示意"><defs><radialGradient id="ehrFilm"><stop stop-color="#394146"/><stop offset="1" stop-color="#10191f"/></radialGradient></defs><rect width="460" height="310" rx="8" fill="url(#ehrFilm)"/><path d="M150 22q-55 30-38 77l-17 23 14 11q-8 41 32 53l17 75h145l-31-96q28-50-6-102-30-49-116-41" fill="#b6c0bb" opacity=".25"/><path d="M140 55q-10 35 17 47l-4 57 40 68" stroke="#bac7c6" stroke-width="6" opacity=".5" fill="none"/><path d="M195 93q26 33 13 81l34 112" stroke="#090e14" stroke-width="16" opacity=".7" fill="none"/>${Array.from({length:6},(_,i)=>`<rect x="${249+i*2}" y="${105+i*27}" width="38" height="17" rx="3" fill="#bfc8c3" opacity=".48" transform="rotate(-8 265 ${113+i*27})"/>`).join('')}${suspected?'<path d="M181 149l13-21" stroke="#ebeee2" stroke-width="3"/>':''}<text x="20" y="25" fill="#b4c7bc" font-size="12">LATERAL VIEW / ONLINE IMAGE</text><text x="230" y="294" fill="#a5b6aa" text-anchor="middle" font-size="11">遊戲示意影像</text></svg>`;}
export function onlineRecordHTML(r,{tab='chart',reportHTML=''}={}){
  const report=tab==='report'&&r.reportTitle;
  return`<section class="ehr-window"><header><span>ENT / 電子病歷</span><b id="modalTitle">線上病歷・影像・檢查報告</b></header><div class="ehr-identity"><strong>${esc(r.name)}</strong><span>${esc(r.title)}</span></div><nav aria-label="電子病歷頁籤"><button data-record-tab="chart" aria-pressed="${!report}">病歷摘要</button>${r.reportTitle?`<button data-record-tab="report" aria-pressed="${!!report}">${esc(r.reportTitle)}</button>`:''}</nav><div class="ehr-content">${report?`${r.type==='xray'?lateralViewSVG(r.suspected):reportHTML}<p class="ehr-report-text">${esc(r.reportText||'檢查報告已在線上系統開啟。')}</p>`:`<dl>${r.rows.map(([label,text])=>`<dt>${esc(label)}</dt><dd>${esc(text)}</dd>`).join('')}</dl>`}</div></section>`;
}
